use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// A bounded work queue supporting cancellation.
///
/// - `push` blocks when the queue is full.
/// - `pop` blocks when the queue is empty.
/// - After `close()`, `push` fails and `pop` drains remaining items then returns `None`.
pub struct WorkQueue<T> {
    inner: Arc<Shared<T>>,
}

struct Shared<T> {
    queue: Mutex<QueueState<T>>,
    not_full: Condvar,
    not_empty: Condvar,
    capacity: usize,
}

struct QueueState<T> {
    items: VecDeque<T>,
    closed: bool,
}

